R = []
def r(id, area, rule, thresholds, source, stype, code, conf, limits, verified="yes"):
    R.append(dict(rule_id=id, area=area, rule=rule, thresholds=thresholds, source=source, source_type=stype, reference_verified=verified, code_location=code, confidence=conf, limitations=limits))

